css:
button {
  background-color: #fff;
  border: 1px solid #2593d3;
  padding: 5px;
  position: relative;
  width: 8rem;
  height: 2em;
  transition: 0.5s;
  font-size: 17px;
  border-radius: 5px;
}

button p {
  position: absolute;
  top: 0.4em;
  left: 1.15em;
  margin: 0;
  padding: 0;
  transition: 0.5s;
  color: #2570d3;
}

button svg {
  position: absolute;
  top: 0.45em;
  right: 0.5em;
  margin: 0;
  padding: 0;
  opacity: 0;
  transition: 0.5s;
  height: 1em;
  fill: #fff;
}

button:hover p {
  left: 0.5em;
  color: #fff;
}

button:hover svg {
  opacity: 1;
}

button:hover {
  background-color: #255cd3;
}
